cat << 'EOF' > src/transport/ws/validation.test.ts
import {validateMessage} from './validation.js';

// One wire name for the client frame: the alias is gone, and the frame the validator returns is the exported shape.

describe('the websocket frame validator', () => {
  it('accepts user_message and returns the frame the exported union describes', () => {
    const result = validateMessage({type: 'user_message', content: 'hello'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('rejects send_message, which is no longer a wire name', () => {
    const result = validateMessage({type: 'send_message', content: 'hello'});

    expect(result).toEqual({valid: false, error: 'Unknown message type: send_message'});
  });

  it('drops any field the frame does not define, rather than forwarding it', () => {
    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  describe('list_sessions', () => {
    it('accepts a bare list_sessions frame ([validated by](specs/hal-engine-conversation-list/spec.md#L76))', () => {
      const result = validateMessage({type: 'list_sessions'});
      expect(result).toEqual({valid: true, data: {type: 'list_sessions'}});
    });

    it('accepts list_sessions with valid limit and before, dropping unknown fields ([validated by](specs/hal-engine-conversation-list/spec.md#L76))', () => {
      const result = validateMessage({
        type: 'list_sessions',
        limit: 10,
        before: {sessionId: 'foo', updatedAt: '2021-01-01T00:00:00.000Z'},
        userId: 'ignored',
      });
      expect(result).toEqual({
        valid: true,
        data: {
          type: 'list_sessions',
          limit: 10,
          before: {sessionId: 'foo', updatedAt: '2021-01-01T00:00:00.000Z'},
        },
      });
    });

    it('rejects list_sessions with non-integer or negative limit ([validated by](specs/hal-engine-conversation-list/spec.md#L76))', () => {
      expect([
        validateMessage({type: 'list_sessions', limit: '10'}),
        validateMessage({type: 'list_sessions', limit: 1.5}),
        validateMessage({type: 'list_sessions', limit: -1}),
      ]).toEqual([
        {valid: false, error: 'limit must be a non-negative integer'},
        {valid: false, error: 'limit must be a non-negative integer'},
        {valid: false, error: 'limit must be a non-negative integer'},
      ]);
    });

    it('rejects list_sessions with malformed before cursor ([validated by](specs/hal-engine-conversation-list/spec.md#L76))', () => {
      expect([
        validateMessage({type: 'list_sessions', before: {sessionId: 'foo'}}),
        validateMessage({type: 'list_sessions', before: {updatedAt: '2021-01-01T00:00:00.000Z'}}),
        validateMessage({type: 'list_sessions', before: {sessionId: '', updatedAt: '2021-01-01T00:00:00.000Z'}}),
        validateMessage({type: 'list_sessions', before: {sessionId: 'a'.repeat(129), updatedAt: 12345}}),
        validateMessage({type: 'list_sessions', before: {sessionId: 'foo', updatedAt: 'not-a-date'}}),
      ]).toEqual([
        {valid: false, error: 'before.updatedAt must be a date string or number'},
        {valid: false, error: 'before.sessionId must be a string of 1-128 characters'},
        {valid: false, error: 'before.sessionId must be a string of 1-128 characters'},
        {valid: false, error: 'before.sessionId must be a string of 1-128 characters'},
        {valid: false, error: 'before.updatedAt must be a valid date string or number'},
      ]);
    });
  });
});
EOF
